    end
    for l = 1:L
        sum(nu(l,:)) <= Pmax*K/L;
        nu(l,:)>=0;
    end
    maximize sum(object)
cvx_end
if contains(cvx_status,‘Solved’) % feasible
    feasible = true;
    nuSolution = nu;
else
